import { createClient } from 'dhcp';

const client = createClient({
    features: ['hostname', 'domainName', 'broadcast'],
    autoRenew: true,
    logLevel: 'info',
});

client.on('bound', (lease) => console.log(lease));
client.on('addressChanged', (previousAddress, currentAddress) => {

    console.log(`Address changed from ${previousAddress} to ${currentAddress}`);
});
client.listen(() => client.sendDiscover());
